    /// <summary>
    /// 整份 sprite，每个页面输出一次
    /// </summary>
    public static IHtmlContent Sprite() {
        var builder = new StringBuilder(16 * 1024);
        _ = builder.Append("""<svg class="icon-sprite" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">""");

        foreach (var (name, body) in Paths) {
            _ = builder.Append("<symbol id=\"i-").Append(name).Append("\" viewBox=\"0 0 24 24\">").Append(body).Append("</symbol>");
        }

        _ = builder.Append("</svg>");
        return new HtmlString(builder.ToString());
    }

    /// <summary>
    /// 引用一个图标，图标本体来自页面里唯一的那份 sprite。
    /// </summary>
    /// <param name="name">Lucide 图标名。</param>
    /// <param name="cssClass">额外的 class。</param>
    /// <param name="label">需要被读屏软件念出来时填写，留空视为纯装饰。</param>
    public static IHtmlContent Icon(string name, string? cssClass = null, string? label = null) {
        if (!Paths.ContainsKey(name)) {
            return HtmlString.Empty;
        }

        var encoder = HtmlEncoder.Default;
        var builder = new StringBuilder(128);

        _ = builder.Append("<svg class=\"icon");
        if (!string.IsNullOrWhiteSpace(cssClass)) {
            _ = builder.Append(' ').Append(encoder.Encode(cssClass));
        }

        _ = builder.Append('"');
        _ = builder.Append(string.IsNullOrWhiteSpace(label)
            ? " aria-hidden=\"true\""
            : $" role=\"img\" aria-label=\"{encoder.Encode(label)}\"");

        _ = builder.Append("><use href=\"#i-").Append(name).Append("\"></use></svg>");
        return new HtmlString(builder.ToString());
    }

    /// <summary>
    /// 把图标整个画出来，不依赖 sprite。
    ///
    /// 提示页是完全独立的一份 HTML，样式和图标都得自带，
    /// 否则主题样式加载不出来的时候它自己也跟着崩。
    /// </summary>
    public static IHtmlContent Inline(string name, string? cssClass = null) {
        if (!Paths.TryGetValue(name, out var body)) {
            return HtmlString.Empty;
        }

        var extra = string.IsNullOrWhiteSpace(cssClass) ? string.Empty : " " + HtmlEncoder.Default.Encode(cssClass);
        return new HtmlString($"""<svg class="icon{extra}" viewBox="0 0 24 24" aria-hidden="true">{body}</svg>""");
    }
}
